def median(values):
    ordered = sorted(values)
    mid = len(ordered) // 2
    return ordered[mid]


def trimmed_mean(values, trim):
    ordered = sorted(values)
    return sum(ordered[trim:-trim]) / len(ordered[trim:-trim])

