def subtotal(items):
    total = 0
    for item in items:
        total += item['qty'] * item['price']
    return total


def tax(items, rate):
    total = 0
    for item in items:
        total += item['qty'] * item['price']
    return round(total * rate, 2)


def grand_total(items, rate):
    total = 0
    for item in items:
        total += item['qty'] * item['price']
    return round(total + total * rate, 2)

